def semver_sort(versions):
    def parse(v):
        # split build metadata
        main_part = v
        if '+' in main_part:
            main_part = main_part.split('+', 1)[0]
        if '-' in main_part:
            core, prerelease = main_part.split('-', 1)
        else:
            core, prerelease = main_part, None

        major, minor, patch = (int(x) for x in core.split('.'))

        if prerelease is None:
            has_pre = 1
            pre_ids = []
        else:
            has_pre = 0
            ids = prerelease.split('.')
            pre_ids = []
            for ident in ids:
                if ident.isdigit():
                    pre_ids.append((0, int(ident)))
                else:
                    pre_ids.append((1, ident))

        return (major, minor, patch, has_pre, pre_ids)

    return sorted(versions, key=parse)

